) AS (
  VALUES 
    (228::BIGINT, 'Tiene favoritismo por ciertos estudiantes, por lo que usted tiene que estar dispuesto a ir a consulta con él lo más posible. Califica duro y no le va a regalar ni un solo punto si usted no le cae bien. En clases no explica porque tiene una pobre administración del tiempo.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2026-11-03T00:00:00+00:00'::TIMESTAMPTZ, '020158b6bb2072148defb97652667d453518306dd5b387a07a30d993a6b69758'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'exelente profe, realmente le importe que los estudiantes pasen, muy claro solo preste mucha atencion, sienpre esta dispuesto a brindar ayuda si ud es ud se ve interesado en la clase, de los mejores profes'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'a6abf760f6c8912c67a8b3327eb9a18a6be960a6c72fa59692c0ecb51acedaf5'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'PARA LAS PERSONAS QUE MENCIONAN LA APARIENCIA FISICA DEL PROFEROR: SI SABEN QUE ESO LE QUITA SERIEDAD A SU CALIFICACION VERDAD, SEAN MAS SERIOS, SI ES GUAPO O NO, NO TIENE NADA QUE VER CON SUS HABILIDADES COMO PROFESOR'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-13T00:00:00+00:00'::TIMESTAMPTZ, 'e88c68490de2e8d4f02a1a90adf585c39c34dc69c995050d2a03afdd888736e1'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Es buen profe, a dt hay q dedicarle bastante tiempo. El mayor consejo es: vayan a consulta, así sea para aclarar dudas pequeñas, él valora mucho q se note el interés, ayuda bastante y creame q incluso puede calificarle más suave que a los demás si ve que usted realmente quiere sacarse nota alta'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2026-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'bc92e84710ffe31cf7d3231fd4004a98ef26f5d1340140a63dc160737012d332'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Es un buen profe, no deja tantas prácticas, pero con las de la cátedra se pasa. El curso no es fácil, pero él siempre muy dispuesto a ayudar, cae muy bien, explica bien, él valora mucho que uno vaya a clases, entonces si pueden evitar faltar mejor. Los asistentes duran muchísimo en calificar.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'ce4b12507e47820dd6a46ba51969362c321b639e62e279dd935b5c1f9ee969f1'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'LLEVEN CON ÉL no se van a arrepentir, explica todo súper bien y aunque dibujo se las trae un poco él no califica duro (sí es muy guapo jaja). Ayuda mucho en consulta y Nada más que los asistentes si son un poco irresponsables o duran mucho revisando las cosas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-29T00:00:00+00:00'::TIMESTAMPTZ, '4eb8353c0c193fe2d2285fe845be2956a97819af5676cdfc5244289792bb1a3c'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Es un excelente profe. Es gracioso, guapillo y se nota que le importa que la gente entienda. El curso en sí es bastante pesado pero si le invierte buen tiempo pasa de fijo con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2025-12-25T00:00:00+00:00'::TIMESTAMPTZ, '234635d1765e21b5e200bd9be75f5679bb6512f30bd118206761ebd9e04f17fc'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Es el mejor profe de mante, ayuda bastante y sabe mucho (también es muy guapo haha). Explica muy bien y tiene mucha paciencia, matricule con el sin duda. Lo unico es que los asistentes duran demasiado calificando y son un poco irresponsables, pero el profe es genial'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-24T00:00:00+00:00'::TIMESTAMPTZ, 'bfde5d66d1059ad79e128fcc87b1b01c1ccd86a8f886ede6c2b072a5ecbefbac'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Es un excelente profesor, es el mejor para matricular dibujo técnico. Es muy agradable, guapo y explica muy bien, sus clases son dinámicas y siempre se asegura de que cada uno de sus estudiantes entienda. Lo único es que dura mucho calificando las tareas, pero fuera de eso, es excelente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-12-23T00:00:00+00:00'::TIMESTAMPTZ, '8bc62ab8a238f7f1730195f686a7e7cb09f3a5b428bdbcf565c9800673a9c1e0'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Demasiado buen profesor, explica excelente y se preocupa por los estudiantes.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, '7372c3030bc16f763fa2e35ba7f73554610eccf3895fba4b0c4a4f823d723496'::TEXT, ARRAY[931]::BIGINT[]),
    (228::BIGINT, 'Demasiado bueno, muy agradable, super claro, ayuda un montón, maneja super bien la materia, cae super bien. Si puede no dude en meter con él. Lo único es que dura mucho en revisar, pero cuando lo hace es muy bueno. Los exámenes si los entrega rápido'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, '00e6a2f9f32c0faa46e1f6dacc1575e5bf9f968dd9c7eb1933cd265d3ae90a34'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'De los mejores profes de la escuela de mante.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-09T00:00:00+00:00'::TIMESTAMPTZ, '511b87f0629830526b66b170710cb2866f7832b61b2e8ab73676f0c706423e02'::TEXT, ARRAY[931]::BIGINT[]),
    (228::BIGINT, 'Frank es el amor de la vida de muchos xd El curso como tal es pesado, pero el profe explica bastante bien y aclara todas las dudas, se nota que le gusta enseñar y hace que las clases no se sientan tan pesadas. Lo único malo es que dura mucho entregando las notas (a excepción de examenes)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2025-12-05T00:00:00+00:00'::TIMESTAMPTZ, '15f33a4cbc18fd49dbb3068d521fb50a12c208b8c24ffc7752efd923d52eabdc'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'No duden en matricular con el DT es un curso pesado pero el profe lo hace bien es muy buena gente y guapo sí jaja si va a consulta con gusto le ayuda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-02T00:00:00+00:00'::TIMESTAMPTZ, '43376a06d791b21be26cbc0a4e15f8ca1183a20230f123420e2d7fee745ea383'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'por dónde empezar, es el mejor profesor dela escuela de mante. Like, no hay comparación, ayuda, explica increíble ah y por allá, es guapo jajajaj y muy simpático; definitivamente matriculen con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2025-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'd4b08f71440b1edbb64737ee0df96d904010f2b2826bf6cdbb42e9af082a3710'::TEXT, ARRAY[931]::BIGINT[]),
    (228::BIGINT, 'El mejor profe sin duda. DT es un curso super pesado pero con Frank se vuelve más llevadero. Explica super bien, ayuda demasiado. Hagan todo lo posible para maticular con él, no se van a arrepentir'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2025-10-07T00:00:00+00:00'::TIMESTAMPTZ, '0fdf7bc6838bae90fd914b1d6aa9d03347eb0bf494299db35a4155be3638f892'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Frank es el mejor profe con el se puede llevar dibujo técnico. Un profe muy humano que intenta conectar con los estudiantes desde el primer segundo. Es un curso pesado, pero el mae logra que usted se interese. Explica demasiado bien y siempre va a buscar la manera de que el estudiante entienda.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2025-08-14T00:00:00+00:00'::TIMESTAMPTZ, '25e7d3ec6d78c18c231b62733bf37a6c0438bac454f4cde0cccffa5e699a4a89'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Frank es el amor de mi vida (y de muchos). Aunque DT sea un curso por sí solo pesado, Frank hace que todo se vea más lindo, las clases son llevaderas y realmente si ud le pone, él lo va a tomar en cuenta, siempre está dispuesto a repetir y ayudar. Su única contra es q dura mil años revisando'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2025-07-30T00:00:00+00:00'::TIMESTAMPTZ, '39a6b403a2eea3350f18cd765a3f789d0d28bdcfd497dc7eadfdb8710409f53c'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'El curso de dt es pesado así que no lo espere regalado tampoco, pero evalúa bastante cómodo. Está siempre dispuesto a ayudar y explica súper bien. Las clases son clarísimas y no se hacen pesadas. Aparte de ser un excelente profe, es simpático, joven y hasta guapo jajaja. Simplemente the GOAT.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2025-07-29T00:00:00+00:00'::TIMESTAMPTZ, 'cf92cf9bb5a3432880f5c14f74b71a88c24bd565233fb232eddd651704b78d2c'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Súuuuuuper buen profe. Cae muy bien y sus clases no son aburridas. Explica bien su materia y tiene bastante dominio. No es tan duro calificando lo de las normas ISO (que tal cosa tiene que estar a tales milímetros o tales grados), además es muy comprensivo. Solo dura mil años para calificar jaja.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2025-07-25T00:00:00+00:00'::TIMESTAMPTZ, '7d13178c5a4957043bd544c4b2a2ab2f0c36c6ce67279664e5302af73ccb7f8c'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'DT es un curso difícil en sí mismo, pero con Frank deidad, se aprende si o si. Explica la materia de forma clara y califica normal. La principal recomendación es acudir a la hora de consulta para salir bien en las tareas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-24T00:00:00+00:00'::TIMESTAMPTZ, '2067c6b9a4321b345b7e66244ec8acd05525a63ef8c55a41dc2f816e8e4628a1'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Excelente profesor, te ayuda en lo que necesites, nunca te trata mal, siempre se devuelve las veces que sean necesarias, hace que el ambiente de clase sea ameno, el mejor para DT, lo volveria a llevar con el mil veces, ayuda un monton en consulta, no te regala puntos, pero tampoco te los quita'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'bf1b7499c8786e24ff105afe4e932ba8d5c29a326fd2fc00c52dd8d5539f1931'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Le gusta enseñar, tiene mucha paciencia, si tiene que devolverse a explicar lo hace de buenas, no regala puntos pero no lo queda, vaya a consulta el le va a explicar hasta que usted entienda, casi que en cualquier momento lo puede contactar y le aclarará sus dudas amablemente. Setarda cn las notas:('::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '540917f31d44d877807e1e11c33be9f9f40fe0d3f45393f3ff9be0bb3b29e0fc'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Pues, buen profe y buena persona, explica bien y da ayuda. Califica muy duro y espera trabajos casi perfectos, pero creo que es el mejor profesor de dibujo tecnico, lo recomiendo si, el curso es dificil de cualquier manera'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '1288ff30fd7d6e443a3c9e5bc14e4be8c40704a5eb59ee27b29157f696f1513d'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'El mejor profe para Dibujo Técnico. Explica bien y ayuda a los estudiantes con las dudas que tengan y sabe mucho de la materia.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, '3e985db0aef7ca1ae4261a87fb5030628bb74237eef7a20602055abb89208576'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'La verdad es un súper buen profesor, explica muy bien y deja mucha práctica extra para prepararse. El curso en si es muy pesado pero si le pones y vas a hora de consulta te servirá mucho. La verdad llevaría el curso con él mil veces más ya que realmente aprendes mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2025-07-02T00:00:00+00:00'::TIMESTAMPTZ, '1c2bdb04f223deba25a656896b2468942651a775c1bfdb85dfc5a95394306f43'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'El profe es excelente explicando, si alguien no entiende el se devuelve para explicarle. Lo único malo es que no sube las notas y uno no sabe cómo va hasta el final del semestre.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, '4b10a0b23733d98a13ab237b96a108c5b98f3617f5e459ac57bf05b574321626'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Posiblemente el mejor profe de dibujo técnico, si tiene la oportunidad de matricular con él, no lo dude. Si no entiende algo puede ir a consulta y le va a ayudar un montón con las tareas. Las clases no se hacen para nada pesadas y da mucha práctica opcional para que se prepare y practique en la casa'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'f062cf80e511dc73b0b805b4e445d8189f35e115e06607eb0ebce256fd591b63'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'La verdad el profe explica muy claro y no califica tan rudo, para este curso que tiene fama de ser muy complicado él es excelente, no "te mueres" y aún así aprendes bastante. Lo único malo es que entrega notas hasta final de semestre, pero si le has puesto de seguro pasas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, '70f24b993427bbab67ed15d4426d7fcd4600b4792797f620c8df113939063a53'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Excelente profesor, le interesa muchísimo el aprendizaje del estudiante y explica todas las veces necesarias. Era muy bueno en consulta. Lo único medio negativo es que se tardaba bastante en entregar las notas de quices. A medio semestre se tuvo que ir a alemania a una maestría.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '71c223c6dd22d135765b853f099c7fed6e5711db00896eb9bc50831db0be6d93'::TEXT, ARRAY[931]::BIGINT[]),
    (228::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2020-12-17T00:00:00+00:00'::TIMESTAMPTZ, '2419c62f13ef2e02b362022aca015fb6416b5be0c1a2f0c8adfd9728038fa296'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Es buen profe. Pero muy irresponsable, dura demasiado para entregar las notas de una evaluación o hasta un enunciado.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-11T00:00:00+00:00'::TIMESTAMPTZ, 'd12747fac1e914e38a797b0f7fc21b36861fa3513735c06b0364e47184166a73'::TEXT, ARRAY[3870, 641]::BIGINT[]),
    (228::BIGINT, 'Muy buen profesor, al curso hay que dedicarle bastante tiempo para realizar prácticas y cualquier duda él se toma el tiempo para discutirla y aclarar los conceptos. Si usted muestra interés, saldrá muy bien en el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-09-08T00:00:00+00:00'::TIMESTAMPTZ, '7ff4b12bdbf1b8062d95d018ab0318863c0f3ae04a3585f102d5cdfc4c51fc7c'::TEXT, ARRAY[947]::BIGINT[]),
    (228::BIGINT, 'Uno de los mejores profesores que he tenido en el tec. Explica todo muy claro y los ejemplos que resuelve son muy útiles para el examen. Da apoyo y constantemente se preocupa por sus estudiantes. Lo único es que sus chistes son muy malos, pero reirse para que no se sienta mal tampoco hace daño.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'eb6929a7850e71c6b1df7296c05c5af3e3096b527bd6e800744a106eb24b6854'::TEXT, ARRAY[931]::BIGINT[]),
    (228::BIGINT, 'Excelente profesor, intentó darnos el apoyo necesario pese a la virtualización del curso. Lo único malo de él es que tarda bastante en revisar las evaluaciones... Si le estresa no saber cómo va puede ser que le moleste, pero por el resto recomendadísimo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '075caa2cfbcf66dfeec44af7670dd59cf59a850b41f661e1c611c9c675f2cdae'::TEXT, ARRAY[931]::BIGINT[]),
    (228::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, '526cef43a337dc013f7ed17478a517a54bf525c3bc4fa93b9ca970a0e6e86a64'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Buen profe, explica muy bien y se preocupa porque uno entienda la materia.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, 'afabcf8ad32547e15223acfe78a33264b0d55fcca2e1dbf5fc97bc6d11d5cda7'::TEXT, ARRAY[641]::BIGINT[]),
    (228::BIGINT, 'Siempre que necesite ayuda el me la brindo, super paciente, de vez en cuando tira una broma para hacer menos pesada la clase, y siempre aclara todo tipo de dudas en las horas de consulta, sin embargo dura mucho subiendo las calificaciones del curso.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2020-07-13T00:00:00+00:00'::TIMESTAMPTZ, 'f6234b739dfaaa5426b760a8e9375499088bae3913ba4dbefc9f90bd4a92b4e8'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'No es muy responsable, aveces deja los trabajos para cuando ya va terminando el modulo de soldadura y hay que hacer el trabajo de soldadura cuando se esta en presiciòn.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Da crédito extra']::TEXT[], '2020-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'aad0503880d927e228cc7d1d423d4cec30d233b6c04b25904d541247958bf301'::TEXT, ARRAY[641]::BIGINT[]),
    (228::BIGINT, 'El único detalle es que es un poco desordenado, los quices y tareas los entrega calificados hasta el final del curso. Si uno ocupa ayuda, no le molesta dar una mano. Bastante paciente. La explicación no es fuera de este mundo, pero no está nada mal.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '134f483a9587f9e018adcc371164e0d2976d69ba59b38d2e0ce1de691d7f194e'::TEXT, ARRAY[931]::BIGINT[]),
    (228::BIGINT, 'Las clases son un poco lentas y aburridas, pero explica muy bien y el curso es fácil y los exámenes suelen tener puntos extra.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Exámenes retadores', 'Respetado por los estudiantes']::TEXT[], '2019-11-18T00:00:00+00:00'::TIMESTAMPTZ, '8135ff25db321f27c37dd57b67c1946b31fd808937b70eae692502d4d6185b82'::TEXT, ARRAY[931]::BIGINT[]),
    (228::BIGINT, 'El mae es súper buena gente. Se compadece de uno si uno tuvo algún fallo. Los quices son fáciles y explica muy bien. Es medio desordenadillo, y la verdad el curso casi no le importa comparado con los otros que da. Califica normal pero deja tareas potentes. Se pasa fácil :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Deja trabajos largos']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'a624ba413700f4ce9ff095e8c0831ba38ace8a94d55051de39c4ece750667c4c'::TEXT, ARRAY[641]::BIGINT[]),
    (228::BIGINT, 'Buena explicación, en partes algo pesada, pero lo necesario para aprobar el curso sin problemas, ademas de que es muy amistoso, recomendado'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-26T00:00:00+00:00'::TIMESTAMPTZ, '347b7b472adf9c4a44a463c512be3794e2f051d76380caa1718a771ba22153fd'::TEXT, ARRAY[931]::BIGINT[]),
    (228::BIGINT, 'De lo mejor de la escuela de mante, explica claro y si no entiende vaya a las horas de consulta y le explica con mucho gusto. Eso si tiene que ponerle que el curso es duro.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2019-01-21T00:00:00+00:00'::TIMESTAMPTZ, '3177a8e10209aa2bbe90e481b15ecfe61a755302a994510abc0985df16ebce18'::TEXT, ARRAY[947]::BIGINT[]),
    (228::BIGINT, 'Explica lo necesario para aprobar el examen, siempre y cuando se haga suficiente práctica individual. Recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '7a9887574a562190a66ae4ef9c65472af7f99bf66f668e09e35f06386e532f1f'::TEXT, ARRAY[931]::BIGINT[]),
    (228::BIGINT, 'Es de los mejores profesores de mante. Da mucho apoyo al estudiante y atiende las dudas que uno tenga sobre la materia sin importar que tan básicas sean'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-23T00:00:00+00:00'::TIMESTAMPTZ, 'a874da13449ba6271ff6be42d739a5af20c70b4befea9f9dce4bc3677b288d1d'::TEXT, ARRAY[947]::BIGINT[]),
    (228::BIGINT, 'Explica muy bien y es compa. Aveces se enreda un toque y dura su rato explicando pero se sale bien con él. Siempre anda chill y es gracioso. Ayuda si uno demuestra interés y es muy accesible. Dura entregando los trabajos. Muy recomendado. Si pudiera, llevaría más cursos con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-09-06T00:00:00+00:00'::TIMESTAMPTZ, '49db944d6990a140be22263f3a3d910e3b27509fb3bdada818b97f4edde4469f'::TEXT, ARRAY[931, 641]::BIGINT[]),
    (228::BIGINT, 'Buen profesor, hace llevadero el curso, habla de muchas más cosas y al menos son interesantes. Es un poco desordenado y un poco desatento. Entrega todas las calificaciones hasta el final.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'c6da60c676443dd24af7ccbb56510b78e62d20303f1cb2ce5e93f17d4a6ba77b'::TEXT, ARRAY[641]::BIGINT[]),
    (228::BIGINT, 'Explica muy bien. Es muy lento entonces a veces hay que llegar los sábados a reponer clase, y dura mucho entregando evaluaciones. Hace ejercicios de buen nivel en clase y ayuda mucho si uno tiene dudas. La mejor opción para dinámica.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '6d59e092f2e2aba4af44fa0e1a828fcabd6b5bb71eb20cce774b78ce34045978'::TEXT, ARRAY[931]::BIGINT[]),
    (228::BIGINT, 'Muy bueno dando el curso. Explica muy claro y ayuda bastante al estudiante. Muy recomendado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'd0f825bbd0cf36cb68d9f6d5ccbb1926c1ab5c49106e7a5b3b02e6386a2f8628'::TEXT, ARRAY[947]::BIGINT[]),
    (228::BIGINT, 'Para ser la primera vez que dio el curso, es por mucho la mejor opción. De vez en cuando pierde mucho el tiempo y hay que reponer clases sábados, quices accesibles.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'a4896f724635f95e159e46ba427e2e4dc5dd01e5fcea5ea494ca543b9047cf82'::TEXT, ARRAY[947]::BIGINT[]),
    (228::BIGINT, 'Es un muy buen profe, explica bastante bien, y evalua con respecto a lo que enseña, lo unico malo es que es dura en entregar las evaluaciones'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'a2f012608906cc8e8069d3461abbe2a7f3928ecf0a11b71668bdd276e924304c'::TEXT, ARRAY[641]::BIGINT[]),
    (228::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-02-02T00:00:00+00:00'::TIMESTAMPTZ, '3d8bf328e2e3e3c79bca7d2aedebcd922d5bc20201221055f123b155e016c484'::TEXT, ARRAY[1726]::BIGINT[]),
    (228::BIGINT, 'Excelente, hace ejercicios de buen nivel y explica muy muy bien'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'e634a6b9eb8252f950fec69f1cf6781ecddae43746210c3a5f938e68af6ec832'::TEXT, ARRAY[1726]::BIGINT[]),
    (228::BIGINT, 'Es un buen profesor, pero no acepta cuando comete errores al explicar'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2018-01-28T00:00:00+00:00'::TIMESTAMPTZ, '8e10d2b968a3cd1c58b40f81c99675937ba389a4722bb76178e5408888e0f792'::TEXT, ARRAY[641]::BIGINT[]),
    (228::BIGINT, 'Explica muy bien, al inicio daba muchos ejercicios y al final no tanto pero al menos los que da son claros y con una dificultad parecida al examen. Deja prácticas y tareas que ayudan mucho para el examen. Sus quices son faciles y el asistente califica suave. Ayuda bastante en los quices.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'efd2303ea4fa5ead184919594de21ba365e02c233d85aca8f54e8187cc9a39e4'::TEXT, ARRAY[1726]::BIGINT[]),
    (228::BIGINT, 'Ayuda bastante para el curso , sin embargo siento que aveces pierde mucho el tiempo'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2018-01-04T00:00:00+00:00'::TIMESTAMPTZ, 'aa46b0a47176795bb911890f86a68d14129874f57b6659a466872d2d796c728b'::TEXT, ARRAY[1726]::BIGINT[]),
    (228::BIGINT, 'El curso es dificil, sin embargo lo hace muy llevadero, Ayuda mucho tanto con sus explicaciones de excelente calidad, como con los ejercicios que hace. Recomedado al 100% Como persona es Muy tuanis y le interesa no solo que aprenda Estatica, si no para la vida'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-09T00:00:00+00:00'::TIMESTAMPTZ, '0b66ca978ae3a8978528e8e430cf75c0bf708f60663b8dabc136cf3749d633d9'::TEXT, ARRAY[1726]::BIGINT[]),
    (228::BIGINT, 'La materia es un poco pesada y enredada, camina por la clase para captar la atención de los estudiantes. Se hace llevadero pero es un poco desordenado, además que no ayuda sin importar los motivos'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-08T00:00:00+00:00'::TIMESTAMPTZ, '0ed6d5c7ed8864c6084dc3e5901a5981b50e352041109d423b857065342580f3'::TEXT, ARRAY[641]::BIGINT[]),
    (228::BIGINT, 'Excelente profesor es claro en sus explicaciones y hace ejercicios de buen nivel, muy recomendado para estática'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '37973fd07112a5b2d5b685690a1bf2ed00d0103fa1a28190aaedcfd9bf0c8218'::TEXT, ARRAY[1726]::BIGINT[]),
    (228::BIGINT, 'Explica claro, ayuda mucho y hace que el curso no sea tan pesado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '554666f09d9a20cf56cb2567159d4d1560648d9ba0bb65ef4ed4e3ac5ffe2818'::TEXT, ARRAY[1726]::BIGINT[]),
    (228::BIGINT, 'Es excelente como profesor y persona, califica normal, explica y realiza muy buenos ejercicios, las clases son entretenidas, la mejor opción para llevar dinámica.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '0c21b7c6f94bb30369a8daf5a13e1e2b1f3055fe3f7ac331001e943a05d18ecc'::TEXT, ARRAY[931]::BIGINT[]),
    (228::BIGINT, 'El curso es muy aburrido pero Frank lo hace llevadero'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, '5d7a5214d22b655ee33cbd657eb84bcc958f1c7186eb36e58ef66cf96011d193'::TEXT, ARRAY[641]::BIGINT[]),
    (228::BIGINT, 'Excelente en todos los aspectos, hace el curso llevadero y se preocupa en que todos entiendan. En consulta también es muy bueno. Además que es guapo y simpático.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-27T00:00:00+00:00'::TIMESTAMPTZ, '1173a0237b3af7c5c6f55323fa75d0aa8cf26566292f54543da308bc459fa047'::TEXT, ARRAY[1726]::BIGINT[]),
    (228::BIGINT, 'Excelente profesor, hace el curso muy llevadero.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'a6e435c984e346d6d7b8a7145f16ce8b2f545f05d5227e32ea2a53ec475f7b72'::TEXT, ARRAY[1726]::BIGINT[]),
    (228::BIGINT, 'Excelente profesor, realmente interesado en que uno pase y aprenda, súper buena nota y explica muy bien. Antes de los exámenes deja prácticas que dejan todo claro. Uno de los mejores profesores que he tenido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'cf9b8939feb05dcf77c8a929c6104e1beabb9bfd68655ea0ad30724fca2e7a95'::TEXT, ARRAY[1726]::BIGINT[]),
    (228::BIGINT, 'Le interesa mucho que los estudiantes aprendan. Por sí solo el curso es difícil pero él trata de facilitarle al estudiante la carga, es relajado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Pocos exámenes']::TEXT[], '2017-11-22T00:00:00+00:00'::TIMESTAMPTZ, '9ff4b1a588db29979cb3676c2dd573ce6c4ddb3cd50c580ed1ba86d672350a6d'::TEXT, ARRAY[1726]::BIGINT[]),
    (228::BIGINT, 'Excelente profesor, maneja un balance perfecto entre dar teoría y resolver ejercicios. Ayuda bastante con quices accesibles y prepara sumamente bien para los exámenes, de los mejores profesores que he tenido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-21T00:00:00+00:00'::TIMESTAMPTZ, '7d601b2ca72f16bec6c7a07479b12be075c6c99bd7f5e6f2f7a57f942bd1a3e9'::TEXT, ARRAY[1726]::BIGINT[]),
    (228::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '3d6d7d1525922d7c96aeb63ee8a32a21190622f80a85a1ed30e3c53afc3e45ab'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Más que un profe, es un amigo. Califica duro, pero se aprende mucho y te prepara para el futuro. MUY RECOMENDADO'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-06-16T00:00:00+00:00'::TIMESTAMPTZ, '5cb1c7efe949645ff1c03962c9bf40ae260d43d431f1287326529d31cde161f1'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Excelente profesor, super recomendado .Muy buena persona, cuando no entiendes algo el siempre te ayuda y procura que uno practique bastante para los examenes.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'facad868580fb746ac7284e364a9807e74840202d615afad345480fd9f3baa0c'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Es una excelente persona y profesor. Realmente le interesa que el estudiante aprenda. Es nuevo dando el curso por lo que es normal que se equivoque. El único problema es que a veces se despista de la clase pero él dice que está trabajando en eso y yo pienso que eso hace la clase más divertida.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'a9a60137805687077e036f3e2a5b313d2b344e3593c811491a5843e0d6ad757a'::TEXT, ARRAY[1726]::BIGINT[]),
    (228::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-07T00:00:00+00:00'::TIMESTAMPTZ, '03e7db620218e340062ba2439998a1e6ae1d5ce570cf0ffa9c13b1963e056461'::TEXT, ARRAY[1726]::BIGINT[]),
    (228::BIGINT, 'Buen profesor y puede llegar a ser un buen amigo también! Aunque a la hora de explicar grupalmente se vuelve un poco confuso, cuando se le pregunta individualmente aclara las dudas muy bien. Califica duro pero por la exigencia del curso. Procura que todos en el grupo se conozcan y se lleven bien.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2017-05-07T00:00:00+00:00'::TIMESTAMPTZ, '5795d1d96b071444bac1eaeb2dff92bed65f883b3e09f8e80b2b2aa0b29b7ba4'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-01-30T00:00:00+00:00'::TIMESTAMPTZ, '3f374ab15cdcd302e04f4dfd7019348aaf3bfd8f387d0c102da8875f2c4e0dd5'::TEXT, ARRAY[1726]::BIGINT[]),
    (228::BIGINT, 'Trata siempre de que todo quede claro. Explica bien y además ayuda bastante.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-14T00:00:00+00:00'::TIMESTAMPTZ, '4fbf244972bac7ddc84075b3b22612d3d96e0e6129cdc48d54d74f44e2246062'::TEXT, ARRAY[1726]::BIGINT[]),
    (228::BIGINT, 'Excelente profesor, ayuda bastante , se preocupa porque el estudiante aprenda y es muy buena persona. Volvería a llevar un curso con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-04T00:00:00+00:00'::TIMESTAMPTZ, 'cc571c5950deed323d81fff18f4ecd74d109d44f8cf6bad0082e154d59f8e230'::TEXT, ARRAY[1726]::BIGINT[]),
    (228::BIGINT, 'excelente persona, como profesor sabe mucho y da buenos consejos para complementar la materia, en los quices ayuda dependiendo del interés del estudiante y se preocupa por preparar lo mejor posible a la clase antes de los exámenes, con nuestro grupo habían días que hacía centros de estudio'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2016-11-28T00:00:00+00:00'::TIMESTAMPTZ, '775eea8e71b503a43fbfa9f55108d81bdf9e34d6b7bbc47b7757c6b4de262822'::TEXT, ARRAY[1726]::BIGINT[]),
    (228::BIGINT, 'No es la gran cosa. Se enreda demasiado y como no califica los exámenes no vale la pena.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-25T00:00:00+00:00'::TIMESTAMPTZ, '786b441b61099a3893d328a92559bcbb83b28bfde0e1fb648445a9cb787bd518'::TEXT, ARRAY[1726]::BIGINT[]),
    (228::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2016-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'e3e351e0e6e7fd174330a950a355c77d71437f03b174f9d7800c1dca89bbdb7d'::TEXT, ARRAY[610]::BIGINT[]),
    (228::BIGINT, 'Es muy bueno y consciente de la dificultad de la materia, muy buena gente y ayuda mucho, brinda atención a los estudiantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-11-04T00:00:00+00:00'::TIMESTAMPTZ, '65aafd6f01716b5b4f51ebcd5d426724a05bbea773b39afc5574fa7877d4c7a8'::TEXT, ARRAY[1726]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
